import unittest

import pricing


class PricingTest(unittest.TestCase):
    def test_behavior_and_refactor(self):
        self.assertEqual(pricing.retail(50), 50)
        self.assertEqual(pricing.wholesale(200), 180)
        self.assertTrue(hasattr(pricing, '_discount_rate'))


if __name__ == '__main__':
    unittest.main()

mock_changes.content:
def _discount_rate(total):
    return 0.1 if total >= 100 else 0


def retail(total):
    return total * (1 - _discount_rate(total))


def wholesale(total):
    return total * (1 - _discount_rate(total))

